1	//! `reasoning_effort` normalization for the OpenAI chat route.
2	//!
3	//! The OpenAI field accepts `none|minimal|low|medium|high|xhigh|max`, but the
4	//! served checkpoint's chat template may know a narrower vocabulary: Qwen3.8's
5	//! accepts only `xhigh|medium|low` and *raises* for anything else, and the
6	//! pinned frontend turns that raise into a 500 rather than a 400
7	//! (`docs/models/qwen35/support-qwen38.md`).
8	//!
9	//! The active rewrite set is derived from the served template itself, once at
10	//! startup: a probe renders a minimal request per candidate value through the
11	//! same vendored renderer the server will use, and a `from -> to` alias is
12	//! enabled only when the template rejects `from` and accepts `to`
13	//! (`high`/`max` → `xhigh`, `minimal` → `low`). A checkpoint whose template
14	//! accepts the OpenAI values — every non-Qwen3.8 line today, Kimi K3 among
15	//! them — gets no rewrite at all, so the caller's values reach it verbatim.
16	//! The probe runs only for saves carrying the `output_gate_type` config
17	//! marker, so other lines pay no startup cost.
18	//!
19	//! `none`, `low`, `medium` and `xhigh` pass through untouched, as does a
20	//! request that carries no top-level field. Two caller-supplied template
21	//! controls are deliberately **not** rewritten: an explicit
22	//! `chat_template_kwargs.reasoning_effort`, which is the caller addressing the
23	//! template directly, and a per-request `chat_template` override, whose
24	//! vocabulary the startup probe never measured. Both keep full control, at the
25	//! cost of their own rejection if the value is outside the template they
26	//! address.
27	
28	use std::path::Path;
29	use std::sync::Arc;
30	
31	use axum::Error as AxumError;
32	use axum::Json;
33	use axum::Router;
34	use axum::body::Body;
35	use axum::body::Bytes;
36	use axum::body::to_bytes;
37	use axum::extract::Request;
38	use axum::extract::State;
39	use axum::http::HeaderValue;
40	use axum::http::Method;
41	use axum::http::StatusCode;
42	use axum::http::header::CONTENT_LENGTH;
43	use axum::middleware;
44	use axum::middleware::Next;
45	use axum::response::IntoResponse;
46	use axum::response::Response;
47	use http_body_util::LengthLimitError;
48	use log::debug;
49	use log::info;
50	use log::warn;
51	use vllm_chat::ChatMessage;
52	use vllm_chat::ChatOptions;
53	use vllm_chat::ChatRequest;
54	use vllm_chat::ChatRole;
55	use vllm_chat::DynChatRenderer;
56	use vllm_chat::EffortValue;
57	use vllm_chat::LoadedModelBackends;
58	use vllm_chat::ResolvedToolContext;
59	use vllm_chat::SamplingParams;
60	use vllm_text::TextDecodeOptions;
61	
62	/// Only the chat route reads `reasoning_effort`.
63	pub(super) const CHAT_COMPLETIONS_PATH: &str = "/v1/chat/completions";
64	
65	/// Matches [`crate::vllm::lora`]'s route limit: the body is buffered to be
66	/// rewritten, and an oversized request must not be silently truncated.
67	pub(super) const BODY_LIMIT: usize = 128 * 1024 * 1024;
68	
69	/// Semantic candidate rewrites between the OpenAI vocabulary and a template's
70	/// own words. Which of them are active is decided per deployment by
71	/// [`probe_effort_aliases`], never assumed from the config alone.
72	const CANDIDATE_ALIASES: &[(&str, &str)] =
73	    &[("high", "xhigh"), ("max", "xhigh"), ("minimal", "low")];
74	
75	/// Values rendered against the loaded template at startup: every alias source
76	/// plus every alias target, so a candidate is armed only on its own verdict.
77	fn probe_values() -> Vec<&'static str> {
78	    let mut values: Vec<&'static str> = Vec::with_capacity(CANDIDATE_ALIASES.len() * 2);
79	    for (from, to) in CANDIDATE_ALIASES {
80	        for value in [from, to] {
81	            if !values.contains(value) {
82	                values.push(value);
83	            }
84	        }
85	    }
86	    values
87	}
88	
89	/// The deployment's active `from -> to` rewrites; empty means "never touch
90	/// the request body".
91	pub(crate) type EffortAliases = Arc<[(&'static str, &'static str)]>;
92	
93	/// Derive the active alias table from the served checkpoint. Only a
94	/// Qwen3.8-class save records the `output_gate_type` marker in its
95	/// `config.json`; for anything else — other lines, or a path with no local
96	/// config at all (e.g. a HuggingFace id) — the probe is skipped entirely and
97	/// the mapping stays off. So is it without loaded backends: without a
98	/// readable template verdict there is no justification to rewrite anything.
99	pub(crate) fn probe_effort_aliases(
100	    model_path: &str,
101	    backends: Option<&LoadedModelBackends>,
102	) -> EffortAliases {
103	    if !probe_warranted(model_path) {
104	        return Vec::new().into();
105	    }
106	    let Some(backends) = backends else {
107	        warn!("reasoning_effort mapping disabled: no loaded template to probe for {model_path}");
108	        return Vec::new().into();
109	    };
110	    let aliases = probe_template(&backends.chat_backend.chat_renderer());
111	    if !aliases.is_empty() {
112	        info!("reasoning_effort mapping for {model_path}: {aliases:?}");
113	    }
114	    aliases.into()
115	}
116	
117	/// The config-marker prefilter: does this checkpoint's save belong to the
118	/// generation whose template is known to restrict `reasoning_effort`? A
119	/// missing directory means the model id is not a local path; a directory
120	/// whose config cannot be read or parsed is an anomaly worth surfacing.
121	fn probe_warranted(model_path: &str) -> bool {
122	    let path = Path::new(model_path);
123	    let config_path = path.join("config.json");
124	    let content = match std::fs::read_to_string(&config_path) {
125	        Ok(content) => content,
126	        Err(error) if path.is_dir() => {
127	            warn!(
128	                "reasoning_effort probe skipped: local model directory {} has no readable config.json: {error}",
129	                path.display()
130	            );
131	            return false;
132	        }
133	        Err(_) => return false,
134	    };
135	    let config: serde_json::Value = match serde_json::from_str(&content) {
136	        Ok(config) => config,
137	        Err(error) => {
138	            warn!(
139	                "reasoning_effort probe skipped: {} is not valid JSON: {error}",
140	                config_path.display()
141	            );
142	            return false;
143	        }
144	    };
145	    let text = config.get("text_config").unwrap_or(&config);
146	    text.get("output_gate_type").is_some()
147	}
148	
149	/// Render one minimal request per candidate value through the renderer the
150	/// server uses, and keep the aliases whose source the template rejects while
151	/// its target is accepted.
152	fn probe_template(renderer: &DynChatRenderer) -> Vec<(&'static str, &'static str)> {
153	    let values = probe_values();
154	    let mut accepted: Vec<(&str, bool)> = Vec::with_capacity(values.len());
155	    for value in values {
156	        accepted.push((value, renderer.render(&probe_request(value)).is_ok()));
157	    }
158	    let accepts = |value: &str| accepted.iter().any(|&(probed, ok)| probed == value && ok);
159	    CANDIDATE_ALIASES
160	        .iter()
161	        .filter(|(from, to)| !accepts(from) && accepts(to))
162	        .copied()
163	        .collect()
164	}
165	
166	/// The smallest request that carries one `reasoning_effort` value: a single
167	/// user turn, every other field at the value the vendored routes resolve for a
168	/// plain text chat. The probe renders it and throws the prompt away.
169	fn probe_request(effort: &str) -> ChatRequest {
170	    ChatRequest {
171	        request_id: "reasoning-effort-probe".to_string(),
172	        messages: vec![ChatMessage::text(ChatRole::User, "probe")],
173	        sampling_params: SamplingParams::default(),
174	        chat_options: ChatOptions {
175	            reasoning_effort: Some(EffortValue::String(effort.to_string())),
176	            ..ChatOptions::default()
177	        },
178	        tool_context: ResolvedToolContext::default(),
179	        decode_options: TextDecodeOptions::default(),
180	        intermediate: false,
181	        prompt_truncation: None,
182	        priority: 0,
183	        documents: None,
184	        cache_salt: None,
185	        add_special_tokens: false,
186	        data_parallel_rank: None,
187	        session_id: None,
188	        lora_request: None,
189	    }
190	}
191	
192	/// Wrap a router so chat requests are normalized before the upstream handler
193	/// converts them. Outermost on purpose: every serving path (plain,
194	/// prefill-only, LoRA) funnels through the router this wraps.
195	pub(crate) fn normalize_chat_requests(router: Router, aliases: EffortAliases) -> Router {
196	    if aliases.is_empty() {
197	        return router;
198	    }
199	    router.layer(middleware::from_fn_with_state(aliases, normalize_request))
200	}
201	
202	async fn normalize_request(
203	    State(aliases): State<EffortAliases>,
204	    request: Request,
205	    next: Next,
206	) -> Response {
207	    if request.method() != Method::POST || request.uri().path() != CHAT_COMPLETIONS_PATH {
208	        return next.run(request).await;
209	    }
210	
211	    let (mut parts, body) = request.into_parts();
212	    let mut bytes = match to_bytes(body, BODY_LIMIT).await {
213	        Ok(bytes) => bytes,
214	        Err(error) => return body_read_error(error),
215	    };
216	
217	    if let Some((from, to)) = rewrite_reasoning_effort(&mut bytes, &aliases) {
218	        debug!("reasoning_effort {from} -> {to}");
219	        parts
220	            .headers
221	            .insert(CONTENT_LENGTH, HeaderValue::from(bytes.len() as u64));
222	    }
223	
224	    next.run(Request::from_parts(parts, Body::from(bytes)))
225	        .await
226	}
227	
228	/// The route's error contract: the same OpenAI-style JSON envelope the
229	/// upstream routes answer with (`vllm_server`'s `ApiError::to_error_response`,
230	/// which is not exported), keeping both the status category and the cause.
231	/// 413 belongs to the length-limit rejection alone; any other read failure
232	/// keeps the 400 this route reported before the layer existed.
233	pub(super) fn body_read_error(error: AxumError) -> Response {
234	    let message = format!("failed to read the chat request body: {error}");
235	    let status = if error.into_inner().is::<LengthLimitError>() {
236	        StatusCode::PAYLOAD_TOO_LARGE
237	    } else {
238	        StatusCode::BAD_REQUEST
239	    };
240	    (
241	        status,
242	        Json(serde_json::json!({
243	            "error": {
244	                "message": message,
245	                "type": "invalid_request_error",
246	                "param": null,
247	                "code": "invalid_request_error",
248	            }
249	        })),
250	    )
251	        .into_response()
252	}
253	
254	/// Rewrite the top-level `reasoning_effort` value in place, returning the
255	/// `(from, to)` pair when it changed. A body that is not JSON, or whose field
256	/// is absent, not a string, or outside the deployment's active aliases, is
257	/// left exactly as it arrived — as is any request carrying its own
258	/// `chat_template`, which renders with a template the startup probe never saw.
259	pub(crate) fn rewrite_reasoning_effort(
260	    body: &mut Bytes,
261	    aliases: &[(&'static str, &'static str)],
262	) -> Option<(String, &'static str)> {
263	    let mut value: serde_json::Value = serde_json::from_slice(body).ok()?;
264	    // The aliases are the *default* template's verdict. A per-request override
265	    // is a different template with its own vocabulary, so rewriting on the
266	    // default's authority can turn a value the override accepts into one it
267	    // rejects. Leave the caller's value for the override to judge.
268	    if value
269	        .get("chat_template")
270	        .is_some_and(serde_json::Value::is_string)
271	    {
272	        return None;
273	    }
274	    let effort = value.get("reasoning_effort")?.as_str()?.to_string();
275	    let to = aliases
276	        .iter()
277	        .find(|(from, _)| *from == effort)
278	        .map(|(_, to)| *to)?;
279	    value["reasoning_effort"] = serde_json::Value::String(to.to_string());
280	    // Serializing a `Value` into a `Vec` cannot fail: every key is already a
281	    // string, and a non-finite number degrades to `null`.
282	    let rewritten = serde_json::to_vec(&value).expect("a serde_json::Value serializes");
283	    *body = Bytes::from(rewritten);
284	    Some((effort, to))
285	}
286	
287	#[cfg(test)]
288	mod tests {
289	    use vllm_chat::LoadModelBackendsOptions;
290	    use vllm_chat::load_model_backends;
291	
292	    use super::*;
293	
294	    const ALL_ALIASES: &[(&str, &str)] = CANDIDATE_ALIASES;
295	
296	    fn rewrite(json: &str) -> (Option<(String, &'static str)>, serde_json::Value) {
297	        let mut body = Bytes::from(json.to_string());
298	        let changed = rewrite_reasoning_effort(&mut body, ALL_ALIASES);
299	        let value = serde_json::from_slice(&body).expect("body stays valid JSON");
300	        (changed, value)
301	    }
302	
303	    #[test]
304	    fn bodies_without_a_rewritable_top_level_field_are_returned_verbatim() {
305	        let (changed, _) = rewrite(r#"{"messages":[{"role":"user","content":"hi"}]}"#);
306	        assert_eq!(changed, None, "no field");
307	
308	        let (changed, value) = rewrite(r#"{"reasoning_effort":7}"#);
309	        assert_eq!(changed, None, "non-string field");
310	        assert_eq!(value["reasoning_effort"], serde_json::json!(7));
311	
312	        let mut body = Bytes::from_static(b"not json at all");
313	        assert_eq!(rewrite_reasoning_effort(&mut body, ALL_ALIASES), None);
314	        assert_eq!(&body[..], b"not json at all");
315	
316	        let (changed, value) = rewrite(r#"{"chat_template_kwargs":{"reasoning_effort":"high"}}"#);
317	        assert_eq!(changed, None, "kwargs-only effort stays the caller's");
318	        assert_eq!(
319	            value["chat_template_kwargs"]["reasoning_effort"],
320	            serde_json::json!("high")
321	        );
322	    }
323	
324	    #[test]
325	    fn a_per_request_template_override_keeps_the_callers_effort_value() {
326	        // The alias table is the *default* template's verdict. An override can
327	        // accept what the default rejects, so guessing for it can break a
328	        // request that would otherwise render.
329	        let (changed, value) = rewrite(r#"{"reasoning_effort":"high","chat_template":"{{ '' }}"}"#);
330	        assert_eq!(
331	            changed, None,
332	            "the override's vocabulary is not ours to know"
333	        );
334	        assert_eq!(value["reasoning_effort"], serde_json::json!("high"));
335	
336	        // No override — an absent or null field renders the default template the
337	        // probe measured, so the mapping applies.
338	        let (changed, _) = rewrite(r#"{"reasoning_effort":"high","chat_template":null}"#);
339	        assert_eq!(changed, Some(("high".to_string(), "xhigh")));
340	    }
341	
342	    // ---- startup probe -------------------------------------------------
343	
344	    const TINY_TOKENIZER_JSON: &str = r#"{
345	      "version": "1.0",
346	      "truncation": null,
347	      "padding": null,
348	      "added_tokens": [
349	        {
350	          "id": 0,
351	          "content": "<unk>",
352	          "single_word": false,
353	          "lstrip": false,
354	          "rstrip": false,
355	          "normalized": false,
356	          "special": true
357	        }
358	      ],
359	      "normalizer": null,
360	      "pre_tokenizer": { "type": "Whitespace" },
361	      "post_processor": null,
362	      "decoder": null,
363	      "model": {
364	        "type": "WordLevel",
365	        "vocab": { "<unk>": 0, "probe": 1 },
366	        "unk_token": "<unk>"
367	      }
368	    }"#;
369	
370	    /// Qwen3.8's stock guard shape: the vocabulary check sits inside the
371	    /// thinking branch and admits only `xhigh|medium|low`.
372	    const GUARDED_TEMPLATE: &str = r"{%- if enable_thinking is undefined or enable_thinking is true %}{%- set resolved = reasoning_effort|default('xhigh') %}{%- if resolved not in ('xhigh', 'medium', 'low') %}{{ raise_exception('Unexpected reasoning effort ' ~ reasoning_effort) }}{%- endif %}{%- endif %}{% for message in messages %}{{ message.content }}{% endfor %}";
373	
374	    /// The review counterexample: a Qwen3.8-marked config whose custom
375	    /// template accepts the OpenAI extremes (`low|high|max`, K3-style). The
376	    /// probe must not arm `high`/`max` rewrites for it.
377	    const ACCEPTING_TEMPLATE: &str = r"{%- set resolved = reasoning_effort|default('high') %}{%- if resolved not in ('low', 'high', 'max') %}{{ raise_exception('Unexpected reasoning effort ' ~ reasoning_effort) }}{%- endif %}{% for message in messages %}{{ message.content }}{% endfor %}";
378	
379	    fn probe_dir(template: &str, marker: bool) -> tempfile::TempDir {
380	        let dir = tempfile::tempdir().expect("tempdir");
381	        std::fs::write(dir.path().join("tokenizer.json"), TINY_TOKENIZER_JSON)
382	            .expect("write tokenizer.json");
383	        let tokenizer_config = serde_json::json!({
384	            "unk_token": "<unk>",
385	            "tokenizer_class": "PreTrainedTokenizerFast",
386	            "chat_template": template,
387	        });
388	        std::fs::write(
389	            dir.path().join("tokenizer_config.json"),
390	            serde_json::to_string(&tokenizer_config).expect("tokenizer_config serializes"),
391	        )
392	        .expect("write tokenizer_config.json");
393	        let mut config = serde_json::json!({
394	            "model_type": "pegainfer_sim",
395	            "max_position_embeddings": 128,
396	            "vocab_size": 16,
397	        });
398	        if marker {
399	            config["text_config"] = serde_json::json!({ "output_gate_type": "swish" });
400	        }
401	        std::fs::write(
402	            dir.path().join("config.json"),
403	            serde_json::to_string(&config).expect("config serializes"),
404	        )
405	        .expect("write config.json");
406	        dir
407	    }
408	
409	    fn path_of(dir: &tempfile::TempDir) -> &str {
410	        dir.path().to_str().expect("utf-8 temp path")
411	    }
412	
413	    async fn renderer_of(dir: &tempfile::TempDir) -> DynChatRenderer {
414	        load_model_backends(
415	            path_of(dir),
416	            LoadModelBackendsOptions {
417	                language_model_only: true,
418	                ..Default::default()
419	            },
420	        )
421	        .await
422	        .expect("the tiny fixture loads")
423	        .chat_backend
424	        .chat_renderer()
425	    }
426	
427	    #[tokio::test]
428	    async fn the_probe_arms_every_alias_for_the_stock_guarded_template() {
429	        let dir = probe_dir(GUARDED_TEMPLATE, true);
430	        let aliases = probe_template(&renderer_of(&dir).await);
431	        assert_eq!(
432	            aliases.as_slice(),
433	            [("high", "xhigh"), ("max", "xhigh"), ("minimal", "low")]
434	        );
435	    }
436	
437	    #[tokio::test]
438	    async fn the_probe_never_arms_a_rewrite_the_template_does_not_need() {
439	        // Same marked config, custom template that accepts high/max: only
440	        // minimal (rejected, with low accepted) may be rewritten.
441	        let dir = probe_dir(ACCEPTING_TEMPLATE, true);
442	        let aliases = probe_template(&renderer_of(&dir).await);
443	        assert_eq!(aliases.as_slice(), [("minimal", "low")]);
444	    }
445	
446	    #[tokio::test]
447	    async fn the_probe_is_skipped_without_the_marker_or_a_local_config() {
448	        let unmarked = probe_dir(GUARDED_TEMPLATE, false);
449	        assert!(
450	            probe_effort_aliases(path_of(&unmarked), None).is_empty(),
451	            "an unmarked save keeps the caller's values verbatim"
452	        );
453	
454	        let missing = "/nonexistent/hf-model-id";
455	        assert!(
456	            probe_effort_aliases(missing, None).is_empty(),
457	            "a path with no local config (an HF id) is not an error"
458	        );
459	    }
460	
461	    // ---- middleware over the real router -------------------------------
462	
463	    fn guarded_app(aliases: EffortAliases) -> Router {
464	        normalize_chat_requests(
465	            Router::new().route(
466	                CHAT_COMPLETIONS_PATH,
467	                axum::routing::post(|| async { "ok" }),
468	            ),
469	            aliases,
470	        )
471	    }
472	
473	    /// Drive the real middleware and return what the caller would see.
474	    async fn chat_post(body: Body) -> (StatusCode, serde_json::Value) {
475	        use tower::ServiceExt as _;
476	
477	        let request = Request::builder()
478	            .method(Method::POST)
479	            .uri(CHAT_COMPLETIONS_PATH)
480	            .body(body)
481	            .expect("request builds");
482	        let response = guarded_app(ALL_ALIASES.to_vec().into())
483	            .oneshot(request)
484	            .await
485	            .expect("the middleware always answers");
486	        let status = response.status();
487	        let bytes = to_bytes(response.into_body(), 64 * 1024)
488	            .await
489	            .expect("response body reads");
490	        let body: serde_json::Value =
491	            serde_json::from_slice(&bytes).expect("the error body is the OpenAI JSON envelope");
492	        (status, body)
493	    }
494	
495	    fn assert_error_envelope(body: &serde_json::Value, cause: &str) {
496	        assert_eq!(
497	            body["error"]["type"],
498	            serde_json::json!("invalid_request_error"),
499	            "{body}"
500	        );
501	        assert!(
502	            body["error"]["message"]
503	                .as_str()
504	                .is_some_and(|m| m.contains(cause)),
505	            "the cause must survive in the envelope: {body}"
506	        );
507	    }
508	
509	    #[tokio::test]
510	    async fn an_oversized_chat_body_is_rejected_as_payload_too_large() {
511	        use futures::StreamExt as _;
512	
513	        let chunk = Bytes::from(vec![0u8; 1024 * 1024]);
514	        let chunks = BODY_LIMIT / chunk.len() + 2;
515	        let body = Body::from_stream(
516	            futures::stream::repeat_with(move || Ok::<Bytes, std::io::Error>(chunk.clone()))
517	                .take(chunks),
518	        );
519	        let (status, body) = chat_post(body).await;
520	        assert_eq!(status, StatusCode::PAYLOAD_TOO_LARGE);
521	        assert_error_envelope(&body, "length limit exceeded");
522	    }
523	
524	    #[tokio::test]
525	    async fn a_truncated_chat_body_keeps_the_bad_request_category_and_the_cause() {
526	        let frames = vec![
527	            Ok::<Bytes, std::io::Error>(Bytes::from_static(br#"{"reasoning_effort":"high","#)),
528	            Err(std::io::Error::new(
529	                std::io::ErrorKind::UnexpectedEof,
530	                "connection closed before the body completed",
531	            )),
532	        ];
533	        let (status, body) = chat_post(Body::from_stream(futures::stream::iter(frames))).await;
534	        assert_eq!(status, StatusCode::BAD_REQUEST);
535	        assert_error_envelope(&body, "connection closed before the body completed");
536	    }
537	}
