88	/// The `vllm_xargs` key carrying the earlier turns' boundaries, newest first.
89	pub(crate) const HISTORY_MARKS: &str = "history_marks";
90	
91	/// How many earlier turns' boundaries are measured, the newest first.
92	const MARKS: usize = 8;
93	
94	/// The route's renderer and tokenizer, held to measure one message at a time.
95	pub(crate) struct Boundary {
96	    renderer: DynChatRenderer,
97	    tokenizer: DynTokenizer,
98	}
99	
100	impl Boundary {
101	    pub(crate) fn new(backends: &LoadedModelBackends) -> Self {
102	        Self {
103	            renderer: backends.chat_backend.chat_renderer(),
104	            tokenizer: backends.text_backend.tokenizer(),
105	        }
106	    }
107	
108	    /// The generation prompt's token count for one chat body, or `None` when
109	    /// the body does not render.
110	    fn generation_prompt_tokens(&self, body: &Value) -> Option<usize> {
111	        let options = chat_options(body);
112	        if !options.add_generation_prompt() {
113	            return Some(0);
114	        }
115	        let message = last_message(body)?;
116	        let with = self.tokens(&message, options.clone())?;
117	        let without = self.tokens(
118	            &message,
119	            ChatOptions {
120	                generation_prompt_mode: GenerationPromptMode::NoGenerationPrompt,
121	                ..options
122	            },
123	        )?;
124	        let shared = with
125	            .iter()
126	            .zip(&without)
127	            .take_while(|(a, b)| a == b)
128	            .count();
129	        Some(with.len() - shared)
130	    }
131	
132	    /// Where the earlier turns of one chat body ended, newest first: the
133	    /// token count of the conversation up to each message an assistant
134	    /// message follows, rendered without a generation prompt.
135	    ///
136	    /// The tools and the tool choice render into the conversation, so each
137	    /// earlier turn is rendered under the body's own, as it was sent.
138	    fn history_marks(&self, body: &Value) -> Vec<usize> {
139	        let choice = match body.get("tool_choice") {
140	            None | Some(Value::Null) => Ok(None),
141	            Some(choice) => tool_choice(choice).map(Some).ok_or(()),
142	        };
143	        let (Some(messages), Some(tools), Ok(choice)) =
144	            (messages(body), tools(body.get("tools")), choice)
145	        else {
146	            return Vec::new();
147	        };
148	        let parallel = body
149	            .get("parallel_tool_calls")
150	            .and_then(Value::as_bool)
151	            .unwrap_or(true);
152	        let ends = (0..messages.len().saturating_sub(1))
153	            .rev()
154	            .filter(|&i| messages[i + 1].role() == vllm_chat::ChatRole::Assistant);
155	        let options = ChatOptions {
156	            generation_prompt_mode: GenerationPromptMode::NoGenerationPrompt,
157	            ..chat_options(body)
158	        };
159	        ends.filter_map(|i| {
160	            let turn = &messages[..=i];
161	            let context =
162	                ResolvedToolContext::new(turn, tools.clone(), choice.clone(), parallel).ok()?;
163	            Some(self.render(turn, options.clone(), context)?.len())
164	        })
165	        .filter(|&m| m > 0)
166	        .take(MARKS)
167	        .collect()
168	    }
169	
170	    /// One message alone, tool-free: what it adds next to the generation
171	    /// prompt does not depend on the tools.
172	    fn tokens(&self, message: &ChatMessage, chat_options: ChatOptions) -> Option<Vec<u32>> {
173	        self.render(
174	            std::slice::from_ref(message),
175	            chat_options,
176	            ResolvedToolContext::default(),
177	        )
178	    }
179	
180	    fn render(
181	        &self,
182	        messages: &[ChatMessage],
183	        chat_options: ChatOptions,
184	        tool_context: ResolvedToolContext,
185	    ) -> Option<Vec<u32>> {
186	        let rendered = self
187	            .renderer
188	            .render(&probe_request(
189	                messages.to_vec(),
190	                chat_options,
191	                tool_context,
192	            ))
193	            .ok()?;
194	        match rendered.prompt {
195	            Prompt::TokenIds(ids) => Some(ids),
196	            Prompt::Text(text) => self.tokenizer.encode(&text, false).ok(),
197	        }
198	    }
199	}
200	
201	/// The template controls the route itself resolves from the body, so the
202	/// probe renders under the same mode, template and kwargs as the prompt.
203	fn chat_options(body: &Value) -> ChatOptions {
204	    let add_generation_prompt = body.get("add_generation_prompt").and_then(Value::as_bool);
205	    let continue_final_message = body
206	        .get("continue_final_message")
207	        .and_then(Value::as_bool)
208	        .unwrap_or(false);
209	    let generation_prompt_mode = match (add_generation_prompt, continue_final_message) {
210	        (_, true) => GenerationPromptMode::ContinueFinalAssistant,
211	        (Some(false), false) => GenerationPromptMode::NoGenerationPrompt,
212	        (None | Some(true), false) => GenerationPromptMode::StartNewAssistant,
213	    };
214	    ChatOptions {
215	        generation_prompt_mode,
216	        chat_template: field(body, "chat_template"),
217	        reasoning_effort: field(body, "reasoning_effort"),
218	        response_format: None,
219	        template_kwargs: field(body, "chat_template_kwargs").unwrap_or_default(),
220	    }
221	}
222	
223	fn field<T: DeserializeOwned>(body: &Value, key: &str) -> Option<T> {
224	    serde_json::from_value(body.get(key)?.clone()).ok()
225	}
226	
227	/// The last message in the route's own vocabulary; the route rejects what
228	/// this layer cannot read.
229	fn last_message(body: &Value) -> Option<ChatMessage> {
230	    message(body.get("messages")?.as_array()?.last()?)
231	}
232	
233	/// Every message, as [`last_message`] reads one; `None` when any does not read.
234	fn messages(body: &Value) -> Option<Vec<ChatMessage>> {
235	    body.get("messages")?
236	        .as_array()?
237	        .iter()
238	        .map(message)
239	        .collect()
240	}
241	
242	fn message(message: &Value) -> Option<ChatMessage> {
243	    let role = message.get("role")?.as_str()?;
244	    let content = match message.get("content") {
245	        None | Some(Value::Null) => ChatContent::Text(String::new()),
246	        Some(Value::String(text)) => ChatContent::Text(text.clone()),
247	        Some(parts) => serde_json::from_value(parts.clone()).ok()?,
248	    };
249	    Some(match role {
250	        "system" => ChatMessage::system(content),
251	        "developer" => {
252	            let tools = tools(message.get("tools"))?;
253	            ChatMessage::developer(content, (!tools.is_empty()).then_some(tools))
254	        }
255	        "user" => ChatMessage::user(content),
256	        "assistant" => assistant(message)?,
257	        "tool" => ChatMessage::tool_response(
258	            content,
259	            message
260	                .get("tool_call_id")
261	                .and_then(Value::as_str)
262	                .unwrap_or_default(),
263	        ),
264	        custom => ChatMessage::custom(custom, content),
265	    })
266	}
267	
268	/// An assistant message as the route reads one: its reasoning, its text and
269	/// its tool calls, in that order, every one of which a template may render
270	/// into the history.
271	fn assistant(message: &Value) -> Option<ChatMessage> {
272	    let reasoning = ["reasoning", "reasoning_content", "thinking"]
273	        .into_iter()
274	        .find_map(|key| message.get(key)?.as_str())
275	        .filter(|text| !text.is_empty())
276	        .map(|text| AssistantContentBlock::Reasoning {
277	            text: text.to_string(),
278	        });
279	    let text = match message.get("content") {
280	        None | Some(Value::Null) => Vec::new(),
281	        Some(Value::String(text)) => vec![AssistantContentBlock::Text { text: text.clone() }],
282	        Some(Value::Array(parts)) => parts
283	            .iter()
284	            .map(|part| match part.get("type")?.as_str()? {
285	                "text" => Some(AssistantContentBlock::Text {
286	                    text: part.get("text")?.as_str()?.to_string(),
287	                }),
288	                _ => None,
289	            })
290	            .collect::<Option<_>>()?,
291	        Some(_) => return None,
292	    };
293	    let calls = match message.get("tool_calls") {
294	        None | Some(Value::Null) => Vec::new(),
295	        Some(Value::Array(calls)) => calls.iter().map(tool_call).collect::<Option<_>>()?,
296	        Some(_) => return None,
297	    };
298	    let blocks: Vec<_> = reasoning.into_iter().chain(text).chain(calls).collect();
299	    (!blocks.is_empty()).then(|| ChatMessage::assistant_blocks(blocks))
300	}
301	
302	fn tool_call(call: &Value) -> Option<AssistantContentBlock> {
303	    let function = call.get("function")?;
304	    (call.get("type")?.as_str()? == "function").then(|| {
305	        Some(AssistantContentBlock::ToolCall(AssistantToolCall {
306	            id: call.get("id")?.as_str()?.to_string(),
307	            name: function.get("name")?.as_str()?.to_string(),
308	            arguments: function
309	                .get("arguments")
310	                .and_then(Value::as_str)
311	                .unwrap_or("{}")
312	                .to_string(),
313	        }))
314	    })?
315	}
316	
317	/// Request-level or message-scoped function tools; `None` when any does not
318	/// read.
319	fn tools(tools: Option<&Value>) -> Option<Vec<ChatTool>> {
320	    match tools {
321	        None | Some(Value::Null) => Some(Vec::new()),
322	        Some(Value::Array(tools)) => tools.iter().map(tool).collect(),
323	        Some(_) => None,
324	    }
325	}
326	
327	fn tool(tool: &Value) -> Option<ChatTool> {
328	    let kind = tool.get("type").map_or(Some("function"), Value::as_str)?;
329	    let function = tool.get("function")?;
330	    let flag = |value: &Value, key| value.get(key).and_then(Value::as_bool);
331	    (kind == "function").then(|| {
332	        Some(ChatTool {
333	            name: function.get("name")?.as_str()?.to_string(),
334	            description: function
335	                .get("description")
336	                .and_then(Value::as_str)
337	                .map(str::to_string),
338	            parameters: function.get("parameters").cloned().unwrap_or_default(),
339	            strict: flag(function, "strict"),
340	            defer_loading: flag(function, "defer_loading").or(flag(tool, "defer_loading")),
341	        })
342	    })?
343	}
344	
345	/// A tool choice the route accepts.
346	fn tool_choice(choice: &Value) -> Option<ChatToolChoice> {
347	    match choice {
348	        Value::String(choice) => match choice.as_str() {
349	            "auto" => Some(ChatToolChoice::Auto),
350	            "none" => Some(ChatToolChoice::None),
351	            "required" => Some(ChatToolChoice::Required),
352	            _ => None,
353	        },
354	        _ if choice.get("type")?.as_str()? == "function" => Some(ChatToolChoice::Function {
355	            name: choice.get("function")?.get("name")?.as_str()?.to_string(),
356	        }),
357	        _ => None,
358	    }
359	}
360	
361	/// Messages under the request's template controls and tools, every other
362	/// field at the value the route resolves for a plain text chat.
363	fn probe_request(
364	    messages: Vec<ChatMessage>,
365	    chat_options: ChatOptions,
366	    tool_context: ResolvedToolContext,
367	) -> ChatRequest {
368	    ChatRequest {
369	        request_id: "history-boundary-probe".to_string(),
370	        messages,
371	        sampling_params: SamplingParams::default(),
372	        chat_options,
373	        tool_context,
374	        decode_options: TextDecodeOptions::default(),
375	        intermediate: false,
376	        prompt_truncation: None,
377	        priority: 0,
378	        documents: None,
379	        cache_salt: None,
380	        add_special_tokens: false,
381	        data_parallel_rank: None,
382	        session_id: None,
383	        lora_request: None,
384	    }
385	}
386	
387	/// Wrap a router so every chat request carries its generation prompt's token
388	/// count and its earlier turns' boundaries into `vllm_xargs`; a server whose
389	/// backends did not load serves the router as is.
390	pub(crate) fn mark_history(router: Router, boundary: Option<Arc<Boundary>>) -> Router {
391	    match boundary {
392	        Some(boundary) => router.layer(middleware::from_fn_with_state(boundary, mark_request)),
393	        None => router,
394	    }
395	}
396	
397	async fn mark_request(
398	    State(boundary): State<Arc<Boundary>>,
399	    request: Request,
400	    next: Next,
401	) -> Response {
402	    if request.method() != Method::POST || request.uri().path() != CHAT_COMPLETIONS_PATH {
403	        return next.run(request).await;
404	    }
405	
406	    let (mut parts, body) = request.into_parts();
407	    let mut bytes = match to_bytes(body, BODY_LIMIT).await {
408	        Ok(bytes) => bytes,
409	        Err(error) => return body_read_error(error),
410	    };
411	
412	    // Rendering and tokenizing up to MARKS prefixes of a long conversation
413	    // takes seconds at 1M tokens: off the async workers.
414	    let (bytes, tokens) = tokio::task::spawn_blocking(move || {
415	        let tokens = mark_generation_prompt(&mut bytes, &boundary);
416	        (bytes, tokens)
417	    })
418	    .await
419	    .expect("the history measure does not panic");
420	    if let Some(tokens) = tokens {
421	        debug!("generation prompt is {tokens} tokens");
422	        parts
423	            .headers
424	            .insert(CONTENT_LENGTH, HeaderValue::from(bytes.len() as u64));
425	    }
426	
427	    next.run(Request::from_parts(parts, Body::from(bytes)))
428	        .await
429	}
430	
431	/// Write the measured count and the earlier turns' boundaries into the body's
432	/// `vllm_xargs`, returning the count when the body changed. A caller's own
433	/// value for either key is replaced: they are this server's measure of its
434	/// own template, not request parameters.
435	fn mark_generation_prompt(body: &mut Bytes, boundary: &Boundary) -> Option<usize> {
436	    let mut value: Value = serde_json::from_slice(body).ok()?;
437	    let tokens = boundary.generation_prompt_tokens(&value)?;
438	    let marks = boundary.history_marks(&value);
439	    let xargs = value
440	        .as_object_mut()?
441	        .entry("vllm_xargs")
442	        .or_insert_with(|| json!({}))
443	        .as_object_mut()?;
444	    xargs.insert(GENERATION_PROMPT_TOKENS.to_string(), json!(tokens));
445	    xargs.insert(HISTORY_MARKS.to_string(), json!(marks));
446	    // Serializing a `Value` into a `Vec` cannot fail: every key is already a
447	    // string, and a non-finite number degrades to `null`.
448	    *body = Bytes::from(serde_json::to_vec(&value).expect("a serde_json::Value serializes"));
449	    Some(tokens)
450	}
451	
452	#[cfg(test)]
453	mod tests {
454	    use std::collections::HashMap;
455	    use std::fmt::Write;
456	
457	    use vllm_chat::ChatRenderer;
458	    use vllm_chat::RenderedPrompt;
459	    use vllm_text::tokenizer::Tokenizer;
460	
461	    use super::*;
462	
463	    /// A template that wraps each message in its role and appends the
464	    /// generation prompt as separate words, except for the tail of a user
465	    /// message ending in `~`, which it glues to the generation prompt so one
466	    /// token straddles the boundary.
467	    struct Template;
468	
469	    impl ChatRenderer for Template {
470	        fn render(&self, request: &ChatRequest) -> vllm_chat::Result<RenderedPrompt> {
471	            let mut text = String::new();
472	            let tools: Vec<_> = request
473	                .initial_tools()
474	                .iter()
475	                .map(|t| t.name.as_str())
476	                .collect();
477	            if !tools.is_empty() {
478	                write!(text, "<tools> {} <end>", tools.join(" ")).unwrap();
479	            }
480	            for message in &request.messages {
481	                let role = serde_json::to_value(message.role()).unwrap();
482	                let mut content = message.text_content()?;
483	                if let ChatMessage::Assistant { content: blocks } = message {
484	                    for block in blocks {
485	                        if let AssistantContentBlock::ToolCall(call) = block {
486	                            write!(content, " call:{}", call.name).unwrap();
487	                        }
488	                    }
489	                }
490	                write!(text, "<{}> {content} <end>", role.as_str().unwrap()).unwrap();
491	            }
492	            if request.chat_options.add_generation_prompt() {
493	                if text.ends_with("~ <end>") {
494	                    text.push_str("<assistant><think>");
495	                } else {
496	                    text.push_str(" <assistant> <think>");
497	                }
498	            }
499	            Ok(RenderedPrompt {
500	                prompt: Prompt::Text(text),
501	                media_order: None,
502	                effective_template_kwargs: HashMap::default(),
503	            })
504	        }
505	    }
506	
507	    /// Whitespace words are tokens; the id is the word's length.
508	    struct Words;
509	
510	    impl Tokenizer for Words {
511	        fn encode(&self, text: &str, _: bool) -> vllm_text::tokenizer::Result<Vec<u32>> {
512	            Ok(text.split_whitespace().map(|w| w.len() as u32).collect())
513	        }
514	        fn encode_ordinary(&self, text: &str) -> vllm_text::tokenizer::Result<Vec<u32>> {
515	            self.encode(text, false)
516	        }
517	        fn decode(&self, _: &[u32], _: bool) -> vllm_text::tokenizer::Result<String> {
518	            unimplemented!()
519	        }
520	        fn token_to_id(&self, _: &str) -> Option<u32> {
521	            None
522	        }
523	        fn id_to_token(&self, _: u32) -> Option<String> {
524	            None
525	        }
526	    }
527	
528	    fn boundary() -> Boundary {
529	        Boundary {
530	            renderer: Arc::new(Template),
531	            tokenizer: Arc::new(Words),
532	        }
533	    }
534	
535	    fn mark(json: &str) -> (Option<usize>, Value) {
536	        let mut body = Bytes::from(json.to_string());
537	        let changed = mark_generation_prompt(&mut body, &boundary());
538	        let value = serde_json::from_slice(&body).expect("body stays valid JSON");
539	        (changed, value)
540	    }
541	
542	    #[test]
543	    fn the_generation_prompt_is_the_tail_the_history_rendering_lacks() {
544	        let (changed, value) = mark(r#"{"messages":[{"role":"user","content":"hi there"}]}"#);
545	        assert_eq!(changed, Some(2), "<assistant> <think>");
546	        assert_eq!(value["vllm_xargs"][GENERATION_PROMPT_TOKENS], json!(2));
547	
548	        let (changed, _) = mark(
549	            r#"{"messages":[{"role":"system","content":"s"},{"role":"tool","content":"out","tool_call_id":"c1"}]}"#,
550	        );
551	        assert_eq!(changed, Some(2), "the last message alone decides");
552	    }
553	
554	    #[test]
555	    fn a_token_straddling_the_boundary_is_counted_as_generation_prompt() {
556	        let (changed, _) = mark(r#"{"messages":[{"role":"user","content":"hi ~"}]}"#);
557	        assert_eq!(
558	            changed,
559	            Some(1),
560	            "`<end><assistant><think>` replaced `<end>`"
561	        );
562	    }
563	
564	    #[test]
565	    fn a_request_without_a_generation_prompt_is_all_history() {
566	        let (changed, _) =
567	            mark(r#"{"messages":[{"role":"user","content":"hi"}],"add_generation_prompt":false}"#);
568	        assert_eq!(changed, Some(0));
569	
570	        let (changed, _) = mark(
571	            r#"{"messages":[{"role":"assistant","content":"so"}],"continue_final_message":true}"#,
572	        );
573	        assert_eq!(changed, Some(0));
574	    }
575	
576	    #[test]
577	    fn the_mark_joins_the_callers_xargs_and_replaces_its_own_key() {
578	        let (changed, value) = mark(
579	            r#"{"messages":[{"role":"user","content":"hi"}],"vllm_xargs":{"kv_transfer_params":1,"generation_prompt_tokens":99}}"#,
580	        );
581	        assert_eq!(changed, Some(2));
582	        assert_eq!(
583	            value["vllm_xargs"],
584	            json!({"kv_transfer_params": 1, GENERATION_PROMPT_TOKENS: 2, HISTORY_MARKS: []})
585	        );
586	    }
587	
588	    #[test]
589	    fn the_earlier_turns_end_where_an_assistant_message_follows() {
590	        // Three turns: each user message followed by an assistant one ended a
591	        // request, measured as the conversation up to it; the last did not.
592	        let (_, value) = mark(
593	            r#"{"messages":[{"role":"system","content":"s"},{"role":"user","content":"a b"},{"role":"assistant","content":"c"},{"role":"user","content":"d"},{"role":"assistant","content":"e f"},{"role":"user","content":"g"}]}"#,
594	        );
595	        // `<system> s <end><user> a b <end>` is 6 words (`<end>` glues to the
596	        // next role), `<assistant> c <end><user> d <end>` 4 more.
597	        assert_eq!(value["vllm_xargs"][HISTORY_MARKS], json!([10, 6]));
598	        let (_, value) = mark(r#"{"messages":[{"role":"user","content":"a"}]}"#);
599	        assert_eq!(value["vllm_xargs"][HISTORY_MARKS], json!([]));
600	    }
601	
602	    #[test]
603	    fn an_earlier_turn_renders_with_the_tools_and_its_tool_calls() {
604	        // `<tools> grep <end><system> s <end><user> a <end>` is 7 words, the
605	        // request that ended there measured 9 with `<assistant> <think>` and a
606	        // 2-word generation prompt; the tool call and its result add
607	        // `<assistant> call:grep <end><tool> out <end>`, 4 more.
608	        let (_, value) = mark(
609	            r#"{"tools":[{"type":"function","function":{"name":"grep"}}],"messages":[{"role":"system","content":"s"},{"role":"user","content":"a"},{"role":"assistant","content":null,"tool_calls":[{"id":"c1","type":"function","function":{"name":"grep","arguments":"{}"}}]},{"role":"tool","content":"out","tool_call_id":"c1"},{"role":"assistant","content":"done"},{"role":"user","content":"b"}]}"#,
610	        );
611	        assert_eq!(value["vllm_xargs"][HISTORY_MARKS], json!([11, 7]));
612	    }
613	
614	    #[test]
615	    fn a_body_the_measure_cannot_read_passes_through_verbatim() {
616	        for json in [
617	            r#"{"prompt":"not a chat"}"#,
618	            r#"{"messages":[]}"#,
619	            r#"{"messages":[{"content":"no role"}]}"#,
620	            r#"{"messages":[{"role":"user","content":"hi"}],"vllm_xargs":7}"#,
621	        ] {
622	            let (changed, value) = mark(json);
623	            assert_eq!(changed, None, "{json}");
624	            assert_eq!(
625	                value,
626	                serde_json::from_str::<Value>(json).unwrap(),
627	                "{json}"
628	            );
629	        }
630	        let mut body = Bytes::from_static(b"not json at all");
631	        assert_eq!(mark_generation_prompt(&mut body, &boundary()), None);
632	        assert_eq!(&body[..], b"not json at all");
633	    }
634	}
